world_checks.check_slack_it_consistency:
def check(world):
    import re
    state = world.state()
    emails = {e["email"].lower(): e["employee_id"] for e in state.get("employees", [])}
    users = {u["user_id"]: u for u in state.get("slack_users", [])}
    reqs = {r["request_id"]: r for r in state.get("access_requests", [])}
    tokens = {a["token"]: a for a in state.get("approvals", [])}
    threads = {m["ts"] for m in state.get("slack_messages", [])}
    for m in state.get("slack_messages", []):
        if m.get("thread_ts") and m["thread_ts"] not in threads:
            return f"{m['message_id']} replies to a missing thread"
        if m["user_id"] == "U_ITDESK":
            # The desk's own reply: it may name any request it handled, but not a token that does not exist.
            for tok in re.findall(r"\bTOK-[A-Z0-9-]+\b", m["text"]):
                if tok not in tokens:
                    return f"{m['message_id']} names token {tok}, which does not exist"
            continue
        author = emails.get(users.get(m["user_id"], {}).get("email", "").lower())
        if not author:
            return f"{m['message_id']} is not from an employee"
        for rid in re.findall(r"\bAR-\d{3}\b", m["text"]):
            r = reqs.get(rid)
            if not r:
                return f"{m['message_id']} names {rid}, which does not exist"
            if author not in (r["employee_id"], r["approver_id"]):
                return f"{m['message_id']} names {rid}, which is not the author's"
        for tok in re.findall(r"\bTOK-[A-Z0-9-]+\b", m["text"]):
            if tok not in tokens:
                return f"{m['message_id']} names token {tok}, which does not exist"
    return None

world_checks.check_it_policy_library:
def check(world):
    import json
    state = world.state()
    today = (state.get("clock") or [{"now": "2026-10-26T09:00:00Z"}])[0]["now"][:10]
    files = [f for f in state.get("drive_files", []) if not f.get("is_deleted")]
    params = {r["name"]: json.loads(r["value"]) for r in state.get("environment_policy", [])}
    for family in ("access_policy", "sod_matrix", "temporary_access"):
        cur = [f for f in files if f["policy_family"] == family and f["status"] == "approved" and f["effective_date"] <= today and f["mime_type"] != "application/octet-stream"]
        if len(cur) != 1:
            return f"{family}: expected one document in effect, found {[f['file_id'] for f in cur]}"
    temp = next(f for f in files if f["policy_family"] == "temporary_access" and f["status"] == "approved")
    if f"at most {params.get('max_temporary_days', 30)} days" not in (temp["content"] or ""):
        return "the temporary access policy does not state the limit the tools enforce"
    acc = next(f for f in files if f["policy_family"] == "access_policy" and f["status"] == "approved" and f["mime_type"] != "application/octet-stream")
    if f"valid for {params.get('approval_token_days', 7)} days" not in (acc["content"] or ""):
        return "the access policy does not state the token validity the tools enforce"
    sod = next(f for f in files if f["policy_family"] == "sod_matrix")
    for rule in state.get("sod_rules", []):
        if rule["role_a"] not in sod["content"] or rule["role_b"] not in sod["content"]:
            return f"the SoD matrix does not list {rule['rule_id']}"
    actor = (state.get("current_actor") or [{}])[0].get("user_id")
    grants = {(p["target_type"], p["target_id"]) for p in state.get("drive_permissions", []) if p["user_id"] == actor}
    if ("folder", "f_secops") in grants or ("folder", "f_it_policies") not in grants:
        return f"{actor}'s Drive access is not the desk's"
    return None

world_checks.check_people_requests_and_tokens:
def check(world):
    """People are distinct, requests name real people and catalogue roles, tokens last the policy's
    days, no application holds more active entitlements than seats, the signed-in caller exists,
    and a Slack message never names a request before that request was raised."""
    import json
    import re
    from datetime import datetime, timezone
    state = world.state()
    emps = {e["employee_id"]: e for e in state.get("employees", [])}
    for table, key in (("employees", "employee_id"), ("slack_users", "user_id")):
        seen = {}
        for row in state.get(table, []):
            email = row["email"].lower()
            if email in seen:
                return f"{table}: {row[key]} and {seen[email]} share the email {email}"
            seen[email] = row[key]
    roles = {(r["app_id"], r["role_name"]) for r in state.get("roles", [])}
    reqs = {r["request_id"]: r for r in state.get("access_requests", [])}
    for r in reqs.values():
        if r["employee_id"] not in emps:
            return f"{r['request_id']} is for {r['employee_id']}, who is not in the directory"
        for who in (r.get("approver_id"), r.get("approved_by")):
            if who and who not in emps:
                return f"{r['request_id']} names approver {who}, who is not in the directory"
        if (r["app_id"], r["role_name"]) not in roles:
            return f"{r['request_id']} asks for {r['role_name']} on {r['app_id']}, which the catalogue does not have"
    params = {row["name"]: json.loads(row["value"]) for row in state.get("environment_policy", [])}
    days = int(params.get("approval_token_days", 7))

    def at(text):
        return datetime.fromisoformat(text.replace("Z", "+00:00"))

    for a in state.get("approvals", []):
        if a["request_id"] not in reqs:
            return f"token {a['token']} is for {a['request_id']}, which does not exist"
        if (at(a["expires_at"]) - at(a["created_at"])).total_seconds() > days * 86400:
            return f"token {a['token']} lasts longer than the {days} days the policy allows"
    seats = {l["app_id"]: l["seats_total"] for l in state.get("app_licenses", [])}
    for app, total in seats.items():
        used = sum(1 for e in state.get("entitlements", []) if e["app_id"] == app and e["status"] == "active")
        if used > total:
            return f"{app} has {used} active entitlements for {total} seats"
    caller = (state.get("session_caller") or [{}])[0].get("employee_id")
    if caller and caller not in emps:
        return f"the signed-in caller {caller} is not in the directory"
    for m in state.get("slack_messages", []):
        posted = datetime.fromtimestamp(float(m["ts"]), tz=timezone.utc)
        for rid in re.findall(r"\bAR-\d{2,3}\b", m["text"]):
            r = reqs.get(rid)
            if r and m["user_id"] != "U_ITDESK" and posted < at(r["created_at"]):
                return f"{m['message_id']} names {rid} before it was raised"
    return None
